import{s as e}from"./i18n-BSBp_gjh.js";import{t}from"./buildPage-DWQZYYcs.js";var n=t({slug:`medical-history`,heroTitle:e({defaultMessage:`Build your complete medical history in minutes`,id:`ffcb25a9da`}),heroSubtitle:e({defaultMessage:`Perplexity Computer organizes every doctor, diagnosis, surgery, and medication into a single portable document automatically.`,id:`b1af74ce56`}),heroCta:e({defaultMessage:`Build my history`,id:`7f89676b0d`}),generatingTitle:e({defaultMessage:`Designing your workflow...`,id:`891de1e6f9`}),inputUrlCta:e({defaultMessage:`Build my history`,id:`02273ed50e`}),inputUrlPlaceholder:`e.g. list your doctors, diagnoses, surgeries, medications, and allergies`,inputUrlPrefill:e({defaultMessage:`Go to {url} and extract every doctor, diagnosis, surgery, medication, allergy, and health event I can remember. Then: 1) Organize everything into a single portable medical history document with sections for conditions, surgeries, medications, allergies, and providers. 2) Create a timeline of major health events. 3) Build a current medication list with dosages and prescribing doctors. 4) Deliver a complete medical history document I can hand a new doctor, use to fill an ER intake form, or give my spouse for emergencies.`,id:`ca0d6b2739`}),heroOverlaySteps:[e({defaultMessage:`Gathering your doctors, diagnoses, surgeries, medications, and allergies`,id:`c1fdebe3ae`}),e({defaultMessage:`Organizing everything into structured sections with a health timeline`,id:`a136b4472c`}),e({defaultMessage:`Building current medication list and provider directory`,id:`29c19c3611`}),e({defaultMessage:`Complete portable medical history — ready to hand to any doctor`,id:`651fe92545`})],generatingSteps:[e({defaultMessage:`Visiting {url} to extract your medical information and health history`,id:`f6bd0e5991`}),e({defaultMessage:`Designing an agent to organize conditions, surgeries, and medications`,id:`ac4e515fb0`}),e({defaultMessage:`Configuring timeline creation, medication tracking, and provider directory`,id:`7261190374`}),e({defaultMessage:`Setting up deliverables — portable medical history document ready for any healthcare setting`,id:`2f502b4831`})],featureSectionTitle:e({defaultMessage:`From scattered records to one portable document`,id:`f8815ad9c0`}),featureCardFirstTitle:e({defaultMessage:`The best model for every task`,id:`b8644b2330`}),featureCardTitles:[e({defaultMessage:`Connects to your health tools`,id:`98379a30a5`}),e({defaultMessage:`Outputs you can act on`,id:`8ee982421a`})],featureCardDescriptions:[e({defaultMessage:`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,id:`b94d4702d2`}),e({defaultMessage:`Google Sheets, Notion, Google Docs, and more — Computer plugs into your tools so your medical history stays accessible and easy to update.`,id:`dbf8a93833`}),e({defaultMessage:`A complete medical history with conditions, surgeries, and allergies. Current medication list with dosages. Provider directory. A health timeline. One document for any doctor visit.`,id:`07034e3731`})],capabilitySectionTitle:e({defaultMessage:`Your health records organizer, on autopilot`,id:`543fe43f8a`}),capabilitySectionSubtitle:e({defaultMessage:`Enter everything you remember, step away, come back to a complete medical history.`,id:`35e9a9326f`}),capabilityCards:[{title:e({defaultMessage:`Deep Research`,id:`2fecfc8138`}),description:e({defaultMessage:`Computer can research your conditions and medications to include relevant clinical details — making your history more useful for new healthcare providers.`,id:`045bd26a39`})},{title:e({defaultMessage:`Record Structuring`,id:`6606736e73`}),description:e({defaultMessage:`Computer can organize unstructured health information into standardized medical history sections — conditions, surgeries, medications, allergies, and family history.`,id:`cb8583fe95`})},{title:e({defaultMessage:`Medication Review`,id:`6679ffb93b`}),description:e({defaultMessage:`Computer can cross-reference your medications for interactions and flag potential conflicts — adding safety notes a new doctor would want to see.`,id:`18cd9f71e7`})},{title:e({defaultMessage:`Connect Your Tools`,id:`4d11fbf3f3`}),description:e({defaultMessage:`Computer can read and write to Google Sheets, Notion, Google Calendar, and more — build workflows that track everything across your entire stack.`,id:`00c33133dd`})},{title:e({defaultMessage:`Remember & Learn`,id:`b7877515c4`}),description:e({defaultMessage:`Computer can remember new diagnoses, medication changes, and doctor visits across sessions — keeping your medical history current without starting over.`,id:`260160c405`})},{title:e({defaultMessage:`Health Event Tracking`,id:`44be9d08dc`}),description:e({defaultMessage:`Computer can monitor for medication refill dates, follow-up appointments, and screening schedules — ensuring your medical record stays complete.`,id:`562d171354`})}]});export{n as default};
